-- 세트 227: Service 가 연결 안 될 때 원인 좁히기: Endpoints, selector 와 라벨, targetPort, readiness
-- 명세: docs/specs/spec_k8s_service_debug_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (227, 1, 'Endpoints 로 연결 상태 보기', 'Service `web` 이 지금 **어느 Pod 로 연결되어 있는지** 봅니다. `kubectl get endpoints web` 의 결과를 `/tmp/ep.txt` 에 저장하세요. 연결이 잘 되어 있으면 ENDPOINTS 칸에 `주소:포트` 가 보입니다. (Service 가 안 될 때 제일 먼저 보는 곳이에요.)', '`kubectl get endpoints web` 의 결과를 `>` 로 파일에 저장하고 `cat` 으로 읽어 보세요. 경고 문구가 화면에 보여도 파일에는 표만 들어갑니다.', 'kubectl get endpoints web -n $NS > /tmp/ep.txt
cat /tmp/ep.txt

# ENDPOINTS 칸에 Pod 주소:80 이 보이면 Service 가 Pod 를 찾은 것이다
# 이 칸이 <none> 이면 Service 가 연결할 Pod 를 하나도 못 찾았다는 뜻이다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q \\"^web \\" /tmp/ep.txt ) && ( grep -Eq \\"^web +[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\\.[0-9]+:80\\" /tmp/ep.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 web 행이 있다", "cmd": ["sh", "-c", "grep -q \\"^web \\" /tmp/ep.txt"]}, {"label": "ENDPOINTS 에 주소:80 이 있다", "cmd": ["sh", "-c", "grep -Eq \\"^web +[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\\.[0-9]+:80\\" /tmp/ep.txt"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 2, 'describe svc 에서 Selector 와 TargetPort 읽기', 'Service `web` 이 **어떤 라벨의 Pod 를 찾는지(Selector)** 와 **Pod 의 어느 포트로 보내는지(TargetPort)** 두 줄만 `/tmp/svc.txt` 에 저장하세요.', '`kubectl describe svc web` 의 긴 출력을 `grep -E ''Selector|TargetPort''` 로 걸러 파일에 저장하세요.', 'kubectl describe svc web -n $NS | grep -E ''Selector|TargetPort'' > /tmp/svc.txt
cat /tmp/svc.txt

# Selector: app=web  → 이 라벨을 가진 Pod 를 찾는다
# TargetPort: 80/TCP → 찾은 Pod 의 80 번 포트로 보낸다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/svc.txt)\\" -eq 2 ] ) && ( grep -Eq \\"Selector: +app=web$\\" /tmp/svc.txt ) && ( grep -Eq \\"TargetPort: +80/TCP\\" /tmp/svc.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/svc.txt)\\" -eq 2 ]"]}, {"label": "Selector 가 app=web 이다", "cmd": ["sh", "-c", "grep -Eq \\"Selector: +app=web$\\" /tmp/svc.txt"]}, {"label": "TargetPort 가 80 이다", "cmd": ["sh", "-c", "grep -Eq \\"TargetPort: +80/TCP\\" /tmp/svc.txt"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 3, 'Pod 라벨 보기', '이번에는 Service 가 연결을 못 하고 있습니다. Service 는 `app=wbe` 라벨을 찾는데, Pod 의 라벨은 무엇일까요? 모든 Pod 의 **라벨까지 함께** 보이는 목록을 `/tmp/labels.txt` 에 저장하고, Service 가 찾는 값과 비교해 보세요.', '`kubectl get pods` 뒤에 `--show-labels` 를 붙이면 맨 오른쪽에 LABELS 칸이 생겨요.', 'kubectl get pods -n $NS --show-labels > /tmp/labels.txt
cat /tmp/labels.txt

# Pod web-1 의 라벨은 app=web 인데 Service 의 Selector 는 app=wbe → 글자가 달라서 못 찾는다 (오타)
# kubectl get endpoints web 을 보면 ENDPOINTS 가 <none> 이다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; kubectl patch svc web -n $NS -p ''{\\"spec\\":{\\"selector\\":{\\"app\\":\\"wbe\\"}}}'' >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q \\"^web-1 \\" /tmp/labels.txt ) && ( grep -Eq \\"^web-1 .* app=web$\\" /tmp/labels.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web-1 행이 있다", "cmd": ["sh", "-c", "grep -q \\"^web-1 \\" /tmp/labels.txt"]}, {"label": "LABELS 칸에 app=web 이 보인다", "cmd": ["sh", "-c", "grep -Eq \\"^web-1 .* app=web$\\" /tmp/labels.txt"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 4, 'kubectl label 로 Pod 라벨 고치기', 'Service `web` 의 Selector 는 `app=web` 인데 Pod `web-1` 의 라벨이 `app=wbe` 로 오타가 났습니다. **Pod 의 라벨을 고쳐서** Service 가 Pod 를 찾게 하세요. (Service 는 그대로 둡니다.)', '`kubectl label pod 이름 키=값` 으로 라벨을 붙입니다. 이미 있는 키의 값을 바꾸려면 `--overwrite` 도 필요해요.', 'kubectl label pod web-1 app=web --overwrite -n $NS
kubectl get endpoints web -n $NS

# 같은 키를 덮어쓰려면 --overwrite 가 필요하다 (없으면 already has a value 오류)
# 라벨을 고치면 곧바로 ENDPOINTS 에 Pod 주소가 채워진다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=wbe -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ] ) && ( [ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.selector.app}'')\\" = web ] ) && ( i=0; while [ $i -lt 10 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod 라벨이 app=web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ]"]}, {"label": "Service Selector 는 그대로 app=web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.selector.app}'')\\" = web ]"]}, {"label": "Endpoints 에 Pod 주소가 있다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 10 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 5, 'selector 를 고치는 patch', 'Pod 의 라벨은 `app=web` 이고 Service `web` 의 selector 가 `app=wbe` 로 틀렸습니다. 이번에는 **Service 쪽을 고치는** patch 명령입니다. 빈칸을 채우세요.', '선택기가 찾아야 할 값은 Pod 가 실제로 가진 라벨 값이에요.', NULL, NULL, '[]', 'fill', '["web", "wbe", "front", "80"]', NULL, 'selector 는 Pod 의 라벨과 글자까지 같아야 합니다. Pod 의 라벨이 `app=web` 이므로 Service 의 selector 도 `web` 으로 맞춥니다. 라벨 오타는 Pod 쪽을 고쳐도(`kubectl label`), Service 쪽을 고쳐도(`kubectl patch`) 풀립니다. 어느 쪽이 의도에 맞는지 보고 고르세요.', '[0]', 'kubectl patch svc web -p ''{"spec":{"selector":{"app":"{0}"}}}''', NULL, NULL),
  (227, 6, 'kubectl patch 로 selector 고치기', 'Pod `web-1` 의 라벨은 `app=web` 인데 Service `web` 의 selector 가 `app=wbe` 로 틀려 있습니다. 이번에는 **Service 의 selector 를 고쳐서** 연결하세요. (Pod 는 그대로 둡니다.)', '`kubectl patch svc web -p ''{"spec":{"selector":{"app":"값"}}}''` 형식입니다. `kubectl edit svc web` 으로 `selector:` 아래를 직접 고쳐도 되지만, 이 터미널에서는 patch 가 편해요.', 'kubectl patch svc web -n $NS -p ''{"spec":{"selector":{"app":"web"}}}''
kubectl get endpoints web -n $NS

# patch 는 지정한 필드만 바꾼다. selector 의 app 만 web 으로 바뀐다
# 고친 뒤에는 get endpoints 에 Pod 주소가 나오는지 꼭 확인한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; kubectl patch svc web -n $NS -p ''{\\"spec\\":{\\"selector\\":{\\"app\\":\\"wbe\\"}}}'' >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.selector.app}'')\\" = web ] ) && ( [ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ] ) && ( i=0; while [ $i -lt 10 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Service selector 가 app=web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.selector.app}'')\\" = web ]"]}, {"label": "Pod 라벨은 그대로 app=web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ]"]}, {"label": "Endpoints 에 Pod 주소가 있다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 10 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 7, '-l 로 Service 가 고르는 Pod 만 모으기', 'Service `web` 의 selector 는 **라벨 두 개가 모두** 맞아야 합니다. selector 를 읽고, 그 조건에 **맞는 Pod 의 이름만** `/tmp/picked.txt` 에 저장하세요. 이름 앞의 `pod/` 는 붙어도 됩니다.', '`kubectl describe svc web` 으로 selector 를 읽은 뒤, `kubectl get pods -l 라벨1,라벨2 -o name` 처럼 쉼표로 이어 쓰면 둘 다 맞는 Pod 만 나와요.', 'kubectl describe svc web -n $NS | grep Selector
kubectl get pods -n $NS -l app=web,tier=front -o name > /tmp/picked.txt
cat /tmp/picked.txt

# -l 에 쉼표로 이은 조건은 모두 맞아야(AND) 한다. Service 의 selector 도 같은 규칙이다
# old-1 은 app=web 이지만 tier=back 이라 Service 가 고르지 않는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.25 --labels=app=web,tier=front -n $NS >/dev/null 2>&1; kubectl run old-1 --image=nginx:1.25 --labels=app=web,tier=back -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 pod/old-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; kubectl patch svc web -n $NS -p ''{\\"spec\\":{\\"selector\\":{\\"app\\":\\"web\\",\\"tier\\":\\"front\\"}}}'' >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(sed \\"s#pod/##\\" /tmp/picked.txt | sort | paste -sd,)\\" = web-1,web-2 ] ) && ( ! grep -q old-1 /tmp/picked.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web-1, web-2 두 개만 있다", "cmd": ["sh", "-c", "[ \\"$(sed \\"s#pod/##\\" /tmp/picked.txt | sort | paste -sd,)\\" = web-1,web-2 ]"]}, {"label": "old-1 은 없다", "cmd": ["sh", "-c", "! grep -q old-1 /tmp/picked.txt"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 8, 'Ready 가 아닌 Pod 를 Ready 로 만들기', 'Pod `web-1` 의 라벨은 Service `web` 과 맞는데 **READY 가 `0/1`** 이라 Endpoints 가 비어 있습니다. Pod 가 준비되지 않은 이유를 찾아 해결하고, Endpoints 에 Pod 주소가 생기게 하세요.', '`kubectl describe pod web-1` 맨 아래 Events 에 `Readiness probe failed` 와 함께 확인하는 명령이 보여요. 그 명령이 성공하도록 만들면 됩니다.', 'kubectl describe pod web-1 -n $NS | grep -i readiness
kubectl exec web-1 -n $NS -- touch /tmp/ready
kubectl get pods -n $NS
kubectl get endpoints web -n $NS

# readinessProbe 가 cat /tmp/ready 를 실행하는데 파일이 없어서 실패 중이었다
# 파일을 만들면 프로브가 통과하고, Ready 가 된 Pod 만 ENDPOINTS 에 들어간다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; printf ''apiVersion: v1\\\\nkind: Pod\\\\nmetadata:\\\\n  name: web-1\\\\n  labels:\\\\n    app: web\\\\nspec:\\\\n  containers:\\\\n  - name: nginx\\\\n    image: nginx:1.25\\\\n    readinessProbe:\\\\n      exec:\\\\n        command: [\\"cat\\", \\"/tmp/ready\\"]\\\\n      periodSeconds: 2\\\\n'' | kubectl apply -n $NS -f - >/dev/null 2>&1; kubectl wait --for=jsonpath=''{.status.phase}''=Running pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:80 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( i=0; while [ $i -lt 15 ]; do if [ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'')\\" = true ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( i=0; while [ $i -lt 15 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod 가 Ready 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 15 ]; do if [ \\"$(kubectl get pod web-1 -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'')\\" = true ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "Endpoints 에 Pod 주소가 있다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 15 ]; do if [ -n \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[0].ip}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 9, 'targetPort 가 틀린 Service 고치기', 'Service `web` 의 Endpoints 에는 Pod 주소가 있는데, 포트가 **80 이 아니라 8080** 이라 접속이 거절됩니다. nginx 는 80 번 포트에서 듣고 있어요. Service 의 **targetPort 를 80 으로** 고치고 Endpoints 의 포트가 바뀌었는지 확인하세요.', '`kubectl get endpoints web` 의 ENDPOINTS 칸에 `주소:포트` 가 보여요. targetPort 는 `kubectl patch svc web --type=json -p ''[{"op":"replace","path":"/spec/ports/0/targetPort","value":값}]''` 로 바꿉니다.', 'kubectl get endpoints web -n $NS
kubectl patch svc web -n $NS --type=json -p ''[{"op":"replace","path":"/spec/ports/0/targetPort","value":80}]''
kubectl get endpoints web -n $NS

# Endpoints 에 주소가 있어도 포트가 틀리면 연결은 거절된다 (selector 문제와 증상이 다르다)
# targetPort 는 Pod(컨테이너)가 실제로 듣는 포트여야 한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:8080 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.ports[0].targetPort}'')\\" = 80 ] ) && ( i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = 80 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "targetPort 가 80 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get svc web -n $NS -o jsonpath=''{.spec.ports[0].targetPort}'')\\" = 80 ]"]}, {"label": "Endpoints 의 포트가 80 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = 80 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 10, 'Endpoints 가 비었는데 Pod 는 1/1 Running 이다', 'Service 에 접속이 안 되고 `kubectl get endpoints` 의 ENDPOINTS 가 `<none>` 입니다. 그런데 Pod 는 `1/1 Running` 으로 멀쩡합니다. **가장 먼저 의심할 것**은 무엇일까요?', 'Pod 가 Ready 라면 준비 문제는 아니에요. Service 가 Pod 를 "찾는" 단계를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["Pod 의 readinessProbe 가 실패하고 있다", "Service 의 selector 와 Pod 의 라벨이 서로 다르다", "Service 의 targetPort 가 컨테이너 포트와 다르다", "노드의 디스크가 가득 찼다"]', 1, 'Pod 가 `1/1` 이면 readinessProbe 문제는 아닙니다(그 경우는 `0/1` 로 보여요). targetPort 가 틀리면 Endpoints 에 주소는 채워지고 포트만 어긋납니다. 목록 자체가 비는 가장 흔한 원인은 selector 와 라벨이 글자까지 맞지 않는 것입니다. `describe svc` 의 Selector 와 `get pods --show-labels` 를 나란히 놓고 비교하세요.', NULL, NULL, NULL, NULL),
  (227, 11, '문제가 두 개 겹친 Service 고치기', 'Service `web` 뒤에 Pod 가 둘(`web-1`, `web-2`) 있는데 Endpoints 에는 **하나만** 있고 포트도 8080 입니다. 원인이 두 개 겹쳐 있어요. 둘 다 찾아 고쳐서 **Pod 두 개가 모두 80 번 포트로** Endpoints 에 들어가게 하세요.', '`get endpoints web` 으로 주소 개수와 포트를 보고, `get pods --show-labels` 로 어느 Pod 의 라벨이 다른지, `describe svc web` 으로 TargetPort 를 확인하세요. 하나씩 고칠 때마다 Endpoints 를 다시 봅니다.', 'kubectl get endpoints web -n $NS
kubectl get pods -n $NS --show-labels
kubectl label pod web-2 app=web --overwrite -n $NS
kubectl patch svc web -n $NS --type=json -p ''[{"op":"replace","path":"/spec/ports/0/targetPort","value":80}]''
kubectl get endpoints web -n $NS

# 증상: 주소 1개(web-1 만) + 포트 8080 → 원인 둘: web-2 라벨 오타(app=wbe), targetPort 8080
# 하나를 고쳐도 다른 하나가 남아 있으니, 고친 뒤마다 get endpoints 로 확인한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod,svc,deploy --all -n $NS --now --wait=true --timeout=60s >/dev/null 2>&1; kubectl run web-1 --image=nginx:1.25 --labels=app=web -n $NS >/dev/null 2>&1; kubectl run web-2 --image=nginx:1.25 --labels=app=wbe -n $NS >/dev/null 2>&1; kubectl wait --for=condition=Ready pod/web-1 pod/web-2 -n $NS --timeout=120s >/dev/null 2>&1; kubectl create service clusterip web --tcp=80:8080 -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[*].ip}'' 2>/dev/null | wc -w)\\" -eq 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = 80 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( [ \\"$(kubectl get pod web-2 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Endpoints 에 주소가 2개이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].addresses[*].ip}'' 2>/dev/null | wc -w)\\" -eq 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "Endpoints 의 포트가 80 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get endpoints web -n $NS -o jsonpath=''{.subsets[0].ports[0].port}'' 2>/dev/null)\\" = 80 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "web-2 라벨이 app=web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod web-2 -n $NS -o jsonpath=''{.metadata.labels.app}'')\\" = web ]"]}]', '[{"title": "Service 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"title": "Service 개념", "url": "https://kubernetes.io/docs/concepts/services-networking/service/"}, {"title": "레이블과 셀렉터", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/"}, {"title": "Readiness 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}]'),
  (227, 12, '연결 안 될 때 원인 좁히는 순서', 'Service 에 접속이 안 될 때 원인을 좁혀 고치는 순서입니다. 순서에 맞게 놓아 보세요.', '먼저 결과(Endpoints)를 보고, 그다음 양쪽(Service·Pod)을 비교하고, 고친 뒤 다시 결과를 봅니다.', NULL, NULL, '[]', 'order', '["`kubectl get endpoints web` 으로 ENDPOINTS 가 비었는지 본다", "`kubectl describe svc web` 으로 Selector 와 TargetPort 를 읽는다", "`kubectl get pods --show-labels` 로 Pod 의 라벨과 READY 를 비교한다", "`kubectl label` 이나 `kubectl patch` 로 라벨·selector·targetPort 를 맞춘다", "`kubectl get endpoints web` 으로 주소가 채워졌는지 다시 확인한다"]', NULL, '결과인 Endpoints 부터 보면 "비었는지, 주소는 있는데 포트가 틀린지"가 갈립니다. 그다음 Service 쪽(Selector, TargetPort)과 Pod 쪽(라벨, READY)을 비교해 어긋난 곳을 찾고, 고친 뒤에는 같은 명령으로 다시 확인해 정말 풀렸는지 봅니다.', '[0, 1, 2, 3, 4]', NULL, NULL, NULL);
